      SUBROUTINE BEAMCC     CALCULATE THE BEAM MATRIX EITHER FROM PARAMETERS ON THE C     BEAM CARD, OR FROM SI AND RC2CC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM7C.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R3P.CIN'      INCLUDE 'SI.CIN'CC     LOCAL VARIABLESC      INTEGER  J, K, JM1CC------------------------------------------------------C     CENTROIDC      DO 1 J = 1, 6      CEN(J) = 0.0      IF (SOFA) CEN(J) = CO(J)    1 CONTINUECC     BEAM MATRIX SAME AS WHEN LAST CALCULATEDC      IF (NORD3 .LT. 1) GO TO 940      IF (R3P) CALL UPDAT3      IF (R2P) GO TO 200      DO 150 J = 1, 6      DO 150 K = 1, 6      SIT(J,K) = SI(J,K)  150 CONTINUE      GO TO 940CC     FIRST-ORDER BEAM MATRIXC  200 CALL BEAM1CC     SECOND-ORDER BEAM MATRIXC      IF (NORD3 .GE. 2) CALL BEAM2CC     THIRD-ORDER BEAM MATRIXC      IF (NORD3 .GE. 3) CALL BEAM3CC     SYMMETRIZATION OF RESULTC  900 DO 920 J = 2, 6      JM1 = J - 1      DO 920 K = 1, JM1      SIT(K,J) = SIT(J,K)  920 CONTINUE  940 RECENT = .TRUE.      RETURN      END